     "Les collaborations dessinent souvent la carte réelle d’une scène mieux que les discours. Pour Miimii KDS, la carte de 2025 et 2026 relie la Guadeloupe à des noms que le public français connaît, tout en gardant le bouyon comme point de départ. Elle se tient ainsi à un endroit stratégique : assez ancrée dans la vague guadeloupéenne pour en être un visage, assez connectée aux albums et aux titres certifiés pour parler à un public plus large, qui la découvre parfois sans connaître encore le mot bouyon.",
     "Notre chapitre <a href=\"/femmes-du-bouyon.html\">femmes du bouyon</a> suit ces trajectoires parce qu’elles changent la place des femmes dans le genre. Les jeunes artistes guadeloupéennes ne sont pas seulement présentes sur les refrains : elles portent des titres sous leur nom, elles sont créditées sur des disques certifiés, elles figurent sur des albums d’artistes établies. Miimii KDS réunit ces trois signes en très peu de temps, ce qui explique l’attention que Bouyon Shattaz porte à la suite de son parcours."
