     "Pour passer de la lecture à l’écoute, notre page <a href=\"/playlist-bouyon.html\">playlist bouyon</a> rassemble les sélections ROAD MIX de Bouyon Shattaz, pensées comme une porte d’entrée dans le son dominicain d’aujourd’hui. Écouter un artiste dans une sélection, au milieu d’autres voix de l’île, permet de comprendre son style par comparaison : le tempo, la voix, l’énergie de groupe et la manière de construire un refrain.",
     "Le hub <a href=\"/artistes-dominique.html\">artistes de la Dominique</a> permet ensuite de circuler entre les profils : les groupes historiques, les chanteuses et chanteurs de la nouvelle génération et les formations de scène qui portent le bouyon au festival. La scène est un ensemble, et c’est cet ensemble que Bouyon Shattaz cherche à rendre visible.",
     "Enfin, le rendez-vous qui rassemble tout ce monde reste le <a href=\"/wcmf-festival-creole.html\">World Creole Music Festival</a>, le WCMF, trois nuits à Roseau qui mettent la musique créole de la Dominique face au public de toute la Caraïbe. C’est dans ce cadre que le profil de Shelly prend son sens le plus concret en 2026."
