     "Le hub <a href=\"/artistes-dominique.html\">artistes de la Dominique</a> permet ensuite de circuler entre les profils : les groupes historiques, les chanteuses et chanteurs de la nouvelle génération et les formations de scène qui portent le bouyon au festival. La scène est un ensemble, et c’est cet ensemble que Bouyon Shattaz cherche à rendre visible.",
     "Enfin, le rendez-vous qui rassemble tout ce monde reste le <a href=\"/wcmf-festival-creole.html\">World Creole Music Festival</a>, le WCMF, trois nuits à Roseau qui mettent la musique créole de la Dominique face au public de toute la Caraïbe. C’est dans ce cadre que le profil de Midnight Groovers prend son sens le plus concret en 2026."
