     "Avant même le bouyon, la Dominique avait déjà une grande tradition de groupes, et <a href=\"/midnight-groovers.html\">Midnight Groovers</a> en est le nom légendaire. Formé à Grand Bay à la fin des années 1960, ce groupe de cadence-lypso est mené par Phillip « Chubby » Mark et compte plus de 39 albums. Un tel catalogue dit quelque chose d’essentiel sur l’île: la musique de groupe, jouée en direct, ancrée dans un village et dans une langue, y est une institution bien avant les plateformes de streaming.",
     "Midnight Groovers figure dans ce roster parce que le bouyon ne naît pas de rien: il pousse sur un sol préparé par la cadence-lypso et les fêtes de village. Derrière le bouyon, il y a des décennies de musique dominicaine, et Grand Bay reste l’un de ses coeurs battants."
